# Independent check: enumerate all 16 truth assignments, keep models of KB, test entailment, and also resolution-style forward chaining
from itertools import product
imp = lambda a, b: (not a) or b
def kb(D, P, R, V):
    return imp(P, R) and imp(D and R, not V) and D and P
models = [m for m in product([False, True], repeat=4) if kb(*m)]
print("models (D,P,R,V):", models)
opts = {
    "A": lambda D, P, R, V: V,
    "B": lambda D, P, R, V: not R,
    "C": lambda D, P, R, V: not V,
    "D": lambda D, P, R, V: imp(P, V),
}
res = {k: bool(models) and all(f(*m) for m in models) for k, f in opts.items()}
print(res)
assert res == {"A": False, "B": False, "C": True, "D": False}
# forward chaining over Horn-style facts as a second method
facts = {"D", "P"}
if "P" in facts: facts.add("R")
if {"D", "R"} <= facts: facts.add("notV")
print(sorted(facts))
assert "notV" in facts and len(models) == 1
